\copy (SELECT orders.order_id, order_date, status, first_name, last_name, name AS perfume, size_ml, quantity, unit_price, quantity * unit_price AS item_total FROM orders INNER JOIN customers ON orders.customer_id = customers.customer_id INNER JOIN order_items ON orders.order_id = order_items.order_id INNER JOIN products ON order_items.product_id = products.product_id ORDER BY orders.order_id, order_item_id) TO 'exports/order_details.csv' WITH (FORMAT CSV, HEADER TRUE)
